    function originalExpandedReading(g){if(g[3]!=='English')return '';if(/acute myeloid leukemia/i.test(g[0]))return '<p><a class="source-guides-link" href="aml-guide.html">Read the full AML patient guide</a></p>';const title=normalizeSearch(g[0]);const links=[[/breast cancer/,'breast-biomarkers','Breast cancer biomarkers'],[/iron deficiency/,'iron-deficiency','Iron-deficiency anemia'],[/type 2 diabetes|^diabetes:/,'type-2-diabetes','Type 2 diabetes'],[/hypertension|high blood pressure/,'blood-pressure','High blood pressure'],[/concussion/,'concussion','Concussion'],[/^depression:|^major depress/,'depression','Depression']];const match=links.find(([pattern])=>pattern.test(title));return match?`<p><a href="health-guides.html#${match[1]}">Read the expanded explainer: ${match[2]}</a></p>`:''}
    function expandedReading(g){const original=originalExpandedReading(g);const key=normalizeSearch(g[0].split(':')[0])+'|'+(g[3]==='Español'?'Spanish':'English');const source=patientGuideLinks[key];if(!source)return original;const es=g[3]==='Español';return original+`<p><a class="source-guides-link" href="guides/${source.id}.html">${es?'Leer información de MedlinePlus':'Read the MedlinePlus patient guide'}: ${source.title}</a>${source.kind==='related-background'?`<span>${es?'Información general relacionada; no es una guía específica para este subtipo.':'Related background, not a guide specific to this subtype.'}</span>`:''}</p>`;}
    function render(){const q=search.value.trim();window.renderGeneMatches?.(q);const shown=findTopics(q);const visible=shown.slice(0,visibleLimit);grid.innerHTML=visible.map(g=>`<details class="condition"><summary><div class="tag">${g[1]}${g[4]?` · ${g[4]}`:''}</div><h3>${g[0]}</h3><span class="lang-badge">${g[3]}</span></summary><div class="condition-body"><p>${g[2]}</p>${expandedReading(g)}<p class="review-note">${g[3]==='Español'?'Resumen breve. Revisión clínica individual no documentada.':'Brief topic summary. Individual clinician review not documented.'} <a href="https://medlineplus.gov/search/?query=${encodeURIComponent(g[0].split(':')[0])}" target="_blank" rel="noopener noreferrer">${g[3]==='Español'?'Buscar información en MedlinePlus':'Find further reading on MedlinePlus'}</a></p><p><strong>${g[3]==='Español'?'Solo para fines educativos.':'For education only.'}</strong> ${g[3]==='Español'?'Las decisiones personales de diagnóstico y tratamiento requieren su propio equipo médico calificado.':'Personal diagnosis and treatment decisions require your own qualified medical team.'}</p></div></details>`).join('');count.textContent=(q?'Found ':'Showing ')+shown.length+' topic entries; '+visible.length+' currently displayed';empty.style.display=shown.length?'none':'block';loadMore.style.display=shown.length>visible.length?'block':'none'}
    document.getElementById('topic-search-form').addEventListener('submit',event=>{event.preventDefault();visibleLimit=24;render();search.blur();const geneMatches=document.getElementById('genetics-matches');const target=geneMatches&&!geneMatches.hidden?geneMatches:(grid.children.length?grid:empty);target.scrollIntoView({block:'start',behavior:'auto'});if(target===grid)grid.focus({preventScroll:true});});
