    function renderIllustrations(){const q=normalizeSearch(illustrationSearch.value);const words=q.split(' ').filter(Boolean);const matches=illustrationCards.filter(card=>words.every(word=>normalizeSearch(card.dataset.topic).includes(word)));const visible=new Set(matches.slice(0,illustrationLimit));illustrationCards.forEach(card=>{card.hidden=!visible.has(card);card.style.display=visible.has(card)?'block':'none'});illustrationCount.textContent=`Showing ${visible.size} of ${matches.length} ${q?'matching ':''}illustrations`;illustrationEmpty.style.display=matches.length?'none':'block';illustrationMore.hidden=matches.length<=illustrationLimit;illustrationMore.textContent='Show '+Math.min(12,Math.max(0,matches.length-illustrationLimit))+' more topics';}
