    function renderPosters(){const q=posterSearch.value.trim().toLowerCase();const words=q.split(/\s+/).filter(Boolean);const seenArt=new Set();const matched=athletePosterGuides.filter(g=>words.every(word=>g.join(' ').toLowerCase().includes(word))).filter(g=>{const topic=posterMessage(g).topic.toLowerCase();const key=individualInjuryPosters[topic]?.id||(topic==='sports concussion'?'concussion-locker-room':null);if(!key)return true;if(seenArt.has(key))return false;seenArt.add(key);return true});const visible=matched.slice(0,posterLimit);posterGrid.innerHTML=visible.map((g,i)=>{const p=posterMessage(g);const specific=individualInjuryPosters[p.topic.toLowerCase()];if(specific)return `<article class="locker-poster" data-poster-image="${specific.image}"><div class="poster-kicker">Student Athlete Strong · ${p.topic}</div><h3>${specific.title}</h3><img class="illustrated-poster-thumb" src="${specific.image.replace(/^posters\/([^/]+)\.(png|webp)$/,'posters/thumbs/$1.webp')}" decoding="async" alt="${p.topic}: individual injury safety poster" loading="lazy"><p>Injury-specific safety poster.</p><div class="poster-actions"><button type="button" data-print-poster>Open illustrated poster</button><a class="related-poster" href="illustrated-posters.html#${specific.id}">Text and sources</a></div></article>`;const art=illustratedPosterCategories[g[4]];const related=art&&(!(g[4]==='Concussion and head safety')||/concussion/i.test(p.topic))?`<p><a class="related-poster" href="illustrated-posters.html#${art.id}">Related illustrated safety poster</a></p>`:'';if(p.topic.toLowerCase()==='sports concussion')return `<article class="locker-poster" data-poster-image="posters/concussion-locker-room.png"><div class="poster-kicker">Concussion safety</div><h3>Protect your brain</h3><img class="illustrated-poster-thumb" src="posters/concussion-locker-room.png" alt="Anatomical concussion safety poster" loading="lazy"><div class="poster-actions"><button type="button" data-print-poster>Open illustrated poster</button></div></article>`;return `<article class="locker-poster" data-poster="${i}"><div class="poster-kicker">Student Athlete Strong · ${g[4]}</div><h3>${p.topic}</h3><div class="poster-rule"></div><p><strong>Focus</strong><br>${p.focus}</p><p>${p.body}</p><p><strong>${p.takeaway}</strong></p>${related}<div class="poster-actions"><button type="button" data-print-poster>Open text reminder</button><span class="poster-brand">Alex Ehsan, MD, PhD<br>Educational only</span></div></article>`}).join('');posterCount.textContent='Showing '+visible.length+' of '+matched.length+' matching posters';posterMore.style.display=matched.length>visible.length?'block':'none';}
    posterSearch.addEventListener('input',()=>{posterLimit=24;renderPosters()});document.getElementById('poster-clear').addEventListener('click',()=>{posterSearch.value='';posterLimit=24;renderPosters();posterSearch.focus()});posterMore.addEventListener('click',()=>{posterLimit+=24;renderPosters()});posterGrid.addEventListener('click',event=>{const button=event.target.closest('[data-print-poster]');if(button)openPosterPreview(button.closest('.locker-poster'))});renderPosters();

    document.querySelector('[data-mental-search]').addEventListener('click',()=>{topicLanguage.value='';active='Mental Health';search.value='';document.querySelectorAll('.filter').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.filter==='Mental Health')));visibleLimit=24;setTimeout(render,0)});
    document.querySelector('[data-mental-spanish]').addEventListener('click',()=>{topicLanguage.value='Español';active='MentalSpanish';search.value='';visibleLimit=24;document.querySelectorAll('.filter').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.filter==='Español')));visibleLimit=24;setTimeout(render,0)});
    document.querySelector('[data-future-search]').addEventListener('click',()=>{topicLanguage.value='';active='Future Sports Medicine';search.value='';document.querySelectorAll('.filter').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.filter==='Future Sports Medicine')));visibleLimit=24;setTimeout(render,0)});
    document.querySelectorAll('[data-future-topic]').forEach(card=>card.addEventListener('click',()=>{topicLanguage.value='';active='Future Sports Medicine';search.value=card.dataset.futureTopic;document.querySelectorAll('.filter').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.filter==='Future Sports Medicine')));visibleLimit=24;setTimeout(render,0)}));
    illustrationCards.forEach(card=>card.addEventListener('click',()=>{topicLanguage.value='';visibleLimit=24;search.value=card.dataset.topic;active='all';document.querySelectorAll('.filter').forEach(x=>x.setAttribute('aria-pressed',x.dataset.filter==='all'?'true':'false'));render()}));
  
const initialQuery=new URLSearchParams(location.search);if(initialQuery.has('q')||initialQuery.has('category'))chooseCategory(initialQuery.get('category')||'all',initialQuery.get('q')||'');
